def _try_spiral_moment_expansion(
    proof: _SpiralMomentProof,
    geometry: RoadGeometry,
    d: _Jet,
    counts: Tuple[Int, Int],
    translation: Vector3,
) -> Optional[Tuple[_Jet, _Jet, _Jet]]:
    if not _sum2_supported_environment():
        return None
