    var accumulated = _ValueJet(
        _Interval(-ideal_magnitude, ideal_magnitude),
        _Interval.whole(),
        _Interval.whole(),
        error,
    )
    var translated = _ValueJet.constant(origin) + accumulated
    if not translated.rounded_value().is_finite():
        return inf[DType.float64]()
    return translated.error

functions._restrict_objective_model:
def _restrict_objective_model(
    model: _ObjectiveModel, low: Float64, high: Float64, scale: Float64
) -> Optional[_Jet]:
    # Cached success never grants authority under a changed floating-point
    # mode. Check this invocation before touching cached arithmetic data.
    if not _sum2_supported_environment():
        return None
    if (
        not isfinite(low)
        or not isfinite(high)
        or high < low
        or low < model.low
        or high > model.high
        or bitcast[DType.uint64](scale) != model.scale_word
    ):
        return None
    var delta = _Interval(low, high) - _Interval.point(model.center_s)
    var value = (
        model.center.value
        + model.center.first * delta
        + _Interval.point(0.5) * model.domain.second * delta.square()
    )
    var first = model.center.first + model.domain.second * delta
    # Both the original whole-cell range and the Taylor restriction enclose
    # the same ideal F(s). Intersect only ordered finite enclosures.
    if not _model_interval(value) or not _model_interval(first):
        return None
    value = _Interval(
        max(value.low, model.domain.value.low),
        min(value.high, model.domain.value.high),
    )
    first = _Interval(
        max(first.low, model.domain.first.low),
        min(first.high, model.domain.first.high),
    )
    if not _model_interval(value) or not _model_interval(first):
        return None
    # These fields enclose F, F' and F'' on the child; they are not the
    # derivatives of the interval-valued quadratic used to compute value.
    # Actual rounded G remains within the same whole-owner uniform error E.
    return _Jet(value, first, model.domain.second, model.domain.error)

functions._minimizer_support:
def _minimizer_support(
    domain: _Jet,
    center: _Jet,
    center_s: Float64,
    best: Float64,
    low: Float64,
    high: Float64,
) -> _Interval:
    # Preconditions: the same ideal branch holds over the complete cell;
    # center encloses that branch at center_s, and best is an actual witness.
    # Only domain.error bounds the actual world-coordinate evaluator.
    var result = _Interval(low, high)
    if (
        not _ordered_finite(result)
        or not isfinite(best)
        or best < low
        or best > high
        or not isfinite(center_s)
        or center_s < low
        or center_s > high
        or not _ordered_finite(domain.value)
        or not isfinite(domain.error)
        or domain.error < 0.0
    ):
        return result
    var derivative = domain.first
    var smooth = _ordered_finite(domain.second) and _ordered_finite(
        center.first
    )
    if smooth:
        var taylor = center.first + domain.second * (
            result - _Interval.point(center_s)
        )
        if _ordered_finite(taylor):
            if _ordered_finite(derivative):
                var joined = _Interval(
                    max(derivative.low, taylor.low),
                    min(derivative.high, taylor.high),
                )
                if not _ordered_finite(joined):
                    return _Interval(low, high)
                derivative = joined
            else:
                derivative = taylor
    var twice_error = _Interval.point(2.0) * _Interval.point(domain.error)
    if _ordered_finite(derivative):
        if derivative.low > 0.0:
            var radius = twice_error / _Interval.point(derivative.low)
            if _ordered_finite(radius):
                var limit = _Interval.point(best) + _Interval.point(radius.high)
                result.high = min(result.high, limit.high)
        elif derivative.high < 0.0:
            var radius = twice_error / _Interval.point(-derivative.high)
            if _ordered_finite(radius):
                var limit = _Interval.point(best) - _Interval.point(radius.high)
                result.low = max(result.low, limit.low)
    if smooth and domain.second.low > 0.0:
        var slope = center.first + domain.second * (
            _Interval.point(best) - _Interval.point(center_s)
        )
        if _ordered_finite(slope):
            var m = _Interval.point(domain.second.low)
            var four_error = _Interval.point(4.0) * _Interval.point(
                domain.error
            )
            var a = _Interval.point(slope.low)
            var b = _Interval.point(slope.high)
            var root_a = (a.square() + four_error * m).sqrt()
            var root_b = (b.square() + four_error * m).sqrt()
            var positive = (-a + root_a) / m
            if slope.low > 0.0:
                positive = four_error / (root_a + a)
            var negative = (b + root_b) / m
            if slope.high < 0.0:
                negative = four_error / (root_b - b)
            if _ordered_finite(positive):
                var limit = _Interval.point(best) + _Interval.point(
                    positive.high
                )
                result.high = min(result.high, limit.high)
            if _ordered_finite(negative):
                var limit = _Interval.point(best) - _Interval.point(
                    negative.high
                )
                result.low = max(result.low, limit.low)
    # Each finite radius encloses a nonnegative exact radius. Outward
    # best +/- radius bounds preserve the incumbent and the original cell.
    return result

functions._sample_dispatch_cut:
def _sample_dispatch_cut(
    origin: Float64, length: Float64, local: Float64
) -> Optional[Float64]:
    # The caller pre-reserves the complete three-candidate attempt.
    if not _sum2_supported_environment():
        return None
    if (
        not isfinite(origin)
        or origin < 0.0
        or not isfinite(length)
        or length <= 0.0
        or not isfinite(local)
        or local < 0.0
        or local >= length
    ):
        return None
    var start = origin + local
    if not isfinite(start) or start <= 0.0:
        return None
    # RN(origin + local) has a predecessor whose predicate is false.
    # If neither of the first two candidates is true, the second successor
    # must be true whenever finite. Its excess over the exact sum is at
    # least 1.5 upward ulps, also larger than local's rounding half-ulp.
    if _sample_dispatch_predicate(origin, length, local, start):
        return start
    var word = bitcast[DType.uint64](start) + UInt64(1)
    if word >= UInt64(0x7FF0000000000000):
        return None
    var cut = bitcast[DType.float64](word)
    if _sample_dispatch_predicate(origin, length, local, cut):
        return cut
    word += UInt64(1)
    if word >= UInt64(0x7FF0000000000000):
        return None
    return bitcast[DType.float64](word)

functions._try_sample_dispatch_cuts:
def _try_sample_dispatch_cuts(
    road: Road,
    low: Float64,
    high: Float64,
    mut nodes: Int,
    mut terms: Int,
    max_nodes: Int,
    max_terms: Int,
) -> Optional[Tuple[Float64, Float64, Int]]:
    if not _sum2_supported_environment():
        return None
    if not isfinite(low) or not isfinite(high) or low <= 0.0 or high < low:
        return None
    var at = info_index(road.info.geometries, low)
    if at < 0 or info_index(road.info.geometries, high) != at:
        return None
    ref record = road.info.geometries[at]
    ref geometry = record.geometry
    if geometry.kind != POLY3 and geometry.kind != PARAM_POLY3:
        return None
    if (
        len(geometry.samples) < 3
        or not isfinite(record.s)
        or record.s < 0.0
        or not isfinite(geometry.length)
        or geometry.length <= 0.0
    ):
        return None
    var dl = min(max(low - record.s, 0.0), geometry.length)
    var dh = min(max(high - record.s, 0.0), geometry.length)
    var first = _sample_index(geometry, dl)
    var last = _sample_index(geometry, dh)
    var count = last - first
    if count < 1 or count > 2:
        return None
    var extra = 8 * count
    var node_reserve = 3 * count + 2
    var term_reserve = 16 * count
    if (
        max_nodes < node_reserve
        or max_terms < 0
        or nodes < 0
        or nodes > max_nodes - node_reserve
        or terms < 0
        or terms > max_terms
        or term_reserve > max_terms - terms
    ):
        return None
    # For c cuts, retain setup + 2c visited descendants + c+1 closed-cell
    # rechecks. Each sampled descendant needs three scalar witnesses and
    # one domain reservation, in addition to the 8c optional probe units.
    # This reserves immediate followup, not completion of an arbitrary
    # remaining search. Setup follows all original node closure choices.
    # One generic node covers at most sixteen predicate/index checks and
    # constant-size packing. Eight reference-equivalent units per cut cover
    # all six possible predicate calls plus two actual sample-index checks.
    # Debit atomically before either complete optional attempt; never refund.
    nodes += 1
    terms += extra
    var one = 0.0
    var two = 0.0
    for i in range(count):
        var threshold_at = first + i + 1
        # The index bracket and count admission put this in [1, n - 2].
        var cut = _sample_dispatch_cut(
            record.s, geometry.length, geometry.samples[threshold_at].s
        )
        if not cut:
            return None
        var station = cut.value()
        # The accepted index bracket makes the cut strictly later than low.
        if station > high:
            return None
        var before = bitcast[DType.float64](
            bitcast[DType.uint64](station) - UInt64(1)
        )
        var before_index = _sample_index(
            geometry, min(max(before - record.s, 0.0), geometry.length)
        )
        var after_index = _sample_index(
            geometry, min(max(station - record.s, 0.0), geometry.length)
        )
        if before_index != threshold_at - 1 or after_index != threshold_at:
            return None
        if i == 0:
            one = station
        else:
            two = station
    return (one, two, count)

functions._grouped_origin_error:
def _grouped_origin_error(
    ideal: _Interval,
    magnitude: _Interval,
    inherited: _Interval,
    count: Int,
    origin: Float64,
) -> Float64:
    # PRIVATE CALLER CONTRACT: only the invocation-guarded raw helper below
    # calls this function, after its successful environment check. The exact
    # caller edges are pinned by the isolated source-correspondence controls.
    # Keep the canonical Sum2 theorem and single final world-origin addition.
    var error = _sum2_error_checked(magnitude.high, inherited.high, count)
    if not isfinite(error) or not ideal.is_finite():
        return inf[DType.float64]()
    var ideal_magnitude = ideal.magnitude()
    var accumulated = _ValueJet(
        _Interval(-ideal_magnitude, ideal_magnitude),
        _Interval.whole(),
        _Interval.whole(),
        error,
    )
    var translated = _ValueJet.constant(origin) + accumulated
    if not translated.rounded_value().is_finite():
        return inf[DType.float64]()
    return translated.error

functions._try_spiral_grouped_roundoff_envelope:
def _try_spiral_grouped_roundoff_envelope(
    geometry: RoadGeometry,
    d: _Jet,
    pieces: Int,
) -> Optional[Tuple[Float64, Float64]]:
    # PRECONDITION: the caller reserved this complete attempt separately from
    # any fallback. The metered adapter below supplies that admission policy.
    # The original caller also owns clamping and the complete count union; this
    # helper must not silently replace that union with one selected count.
    if not _sum2_supported_environment():
        return None
    var rate = _spiral_grouped_domain_rate(geometry, d, pieces)
    if not rate:
        return None
    var rate_value = rate.value()
    var nodes = materialize[_GL_NODES]()
    var weights = materialize[_GL_WEIGHTS]()
    # Materialized copies come only from these immutable compile-time tables.
    # Reject an incompatible table at compilation, before this helper can run.
    # The stored pair multiplicities remain 2,2,1; no ideal weight sum is used.
    comptime assert _GL_WEIGHTS[0] == _GL_WEIGHTS[4]
    comptime assert _GL_WEIGHTS[1] == _GL_WEIGHTS[3]
    comptime assert _GL_WEIGHTS[0] > 0.0 and _GL_WEIGHTS[0] <= 1.0
    comptime assert _GL_NODES[0] > -1.0 and _GL_NODES[0] < 1.0
    comptime assert _GL_WEIGHTS[1] > 0.0 and _GL_WEIGHTS[1] <= 1.0
    comptime assert _GL_NODES[1] > -1.0 and _GL_NODES[1] < 1.0
    comptime assert _GL_WEIGHTS[2] > 0.0 and _GL_WEIGHTS[2] <= 1.0
    comptime assert _GL_NODES[2] > -1.0 and _GL_NODES[2] < 1.0
    comptime assert _GL_WEIGHTS[3] > 0.0 and _GL_WEIGHTS[3] <= 1.0
    comptime assert _GL_NODES[3] > -1.0 and _GL_NODES[3] < 1.0
    comptime assert _GL_WEIGHTS[4] > 0.0 and _GL_WEIGHTS[4] <= 1.0
    comptime assert _GL_NODES[4] > -1.0 and _GL_NODES[4] < 1.0
    var node_low = inf[DType.float64]()
    var node_high = -inf[DType.float64]()
    for i in range(5):
        var node = 1.0 + nodes[i]
        node_low = min(node_low, node)
        node_high = max(node_high, node)
    var distance = _ValueJet(
        d.value, _Interval.whole(), _Interval.whole(), d.error
    )
    var step = distance / _ValueJet.constant(Float64(pieces))
    var half_step = _stored_half(step)
    var half_rate = _stored_half(_ValueJet.constant(rate_value))
    var node_range = _grouped_constant(node_low, node_high)
    var phases = Array[_ValueJet, 4](fill=_ValueJet.constant(0.0))
    # Establish every group's original rounded phase branch before the first
    # polynomial evaluation. An ineligible later group cannot waste trig work.
    for group in range(4):
        var low = group * pieces // 4
        var high = (group + 1) * pieces // 4
        if low == high:
            continue
        var start = step * _grouped_constant(Float64(low), Float64(high - 1))
        var t = start + half_step * node_range
        var theta = _ValueJet.constant(geometry.heading) + t * (
            _ValueJet.constant(geometry.curvature_start) + half_rate * t
        )
        var phase = theta.rounded_value()
        if not phase.is_finite() or phase.magnitude() > _PHASE_LIMIT:
            return None
        var selection = (
            theta * _ValueJet.constant(_INV_HALF_PI) + _ValueJet.constant(0.5)
        ).rounded_value()
        # The ordered theta and nonnegative error are bounded by the phase gate.
        # Multiplication by k<=1 and addition of 0.5 cannot overflow this selector.
        comptime assert _INV_HALF_PI > 0.0 and _INV_HALF_PI <= 1.0
        comptime assert _PHASE_LIMIT > 0.0 and _PHASE_LIMIT <= 1048576.0
        if floor(selection.low) != 0.0 or floor(selection.high) != 0.0:
            return None
        phases[group] = theta
    var factors = Array[_ValueJet, 3](fill=_ValueJet.constant(0.0))
    for weight in range(3):
        factors[weight] = half_step * _ValueJet.constant(weights[weight])
    var x_ideal = _Interval.point(0.0)
    var y_ideal = _Interval.point(0.0)
    var x_magnitude = _Interval.point(0.0)
    var y_magnitude = _Interval.point(0.0)
    var x_inherited = _Interval.point(0.0)
    var y_inherited = _Interval.point(0.0)
    for group in range(4):
        var low = group * pieces // 4
        var high = (group + 1) * pieces // 4
        if low == high:
            continue
        var trig = _sincos_expression(phases[group])
        for weight in range(3):
            var multiplicity = 1 if weight == 2 else 2
            var copies = (high - low) * multiplicity
            var x = factors[weight] * trig[1]
            var y = factors[weight] * trig[0]
            if not _grouped_term(x, copies, x_ideal, x_magnitude, x_inherited):
                return None
            # The source-bound Y-finiteness lemma proves this call succeeds
            # after X. Keep the call and all three accumulator writes.
            _ = _grouped_term(y, copies, y_ideal, y_magnitude, y_inherited)
    var x_error = _grouped_origin_error(
        x_ideal, x_magnitude, x_inherited, 5 * pieces, geometry.x
    )
    var y_error = _grouped_origin_error(
        y_ideal, y_magnitude, y_inherited, 5 * pieces, geometry.y
    )
    if not isfinite(x_error) or not isfinite(y_error):
        return None
    return (x_error, y_error)
